new_string:
bfree_coop_as_switch_to(1);
{
    uint64_t rip = g_coop_child_rcx;
    page_table_t *cpt = bfree_process_child_pt();
    uint64_t paddr = 0;
    uint64_t pte = 0;
    uint64_t pd_index = (rip >> 21) & 0x1FFULL;
    uint64_t pt_index = (rip >> 12) & 0x1FFULL;
    unsigned char buf[8];
    unsigned i;

    uart_puts("[COOP] child rip=");
    uart_puthex64(rip);
    if (cpt) {
        uart_puts(" pd=");
        uart_puthex64(cpt->pd[pd_index]);
        {
            pte_t *slot = &cpt->pt[pd_index][0];
            pte = slot[pt_index];
            uart_puts(" pte=");
            uart_puthex64(pte);
        }
    }
    bfree_kernel_phys_io_begin();
    if (cpt && vmm_user_virt_to_phys(cpt, rip, &paddr) == 0) {
        uart_puts(" phys=");
        uart_puthex64(paddr);
        if (bfree_kernel_peek_phys(paddr + (rip & (PAGE_SIZE - 1ULL)), buf, 8) == 0) {
            uart_puts(" bytes=");
            for (i = 0; i < 8; ++i) {
                uart_puthex64((uint64_t)buf[i]);
                uart_puts(" ");
            }
        }
    } else {
        uart_puts(" NO_USER_PTE");
    }
    bfree_kernel_phys_io_end();
    uart_puts("\n");
}
uart_puts("[COOP] yield_child switched\n");
g_coop_child_blocked = 0;
